      "path": "src/index.ts",
      "content": "/**\n * dsh-side-session host half: registers one host slash command, `/side-chat`\n * (旁会话), that spawns a durable, continuable subagent side-session under\n * the calling agent — with zero UI of its own.\n *\n * Why a host command and not a browser RPC:\n *  - The GUI's \"＋\" menu is the `/` command source. A host command with no\n *    input descriptor appears there and, when picked, runs *detached* (no\n *    argument claim, no popup — the dispatch table's bare-host-command arm).\n *  - `ctx.commands` already mounts in dsh-base, and the command handler\n *    receives the LIVE parent `agent`, which is exactly what\n *    `ctx.subagents.startContinuable` requires. No Typert Remote, no panel,\n *    no header button needed.\n *\n * The child gets a fixed \"ready\" opening prompt and an auto timestamp label;\n * the browser half listens for `command/executed` and jumps straight into the\n * child's official chat view, where the user takes over the conversation.\n * The main session is never prompted or touched.\n *\n * @module dsh-side-session\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\n// Type-only: brings the ctx.subagents Context merge into this program.\nimport type {} from '@deepseek-ai/dsh-subagent'\n// Type-only: brings the ctx.commands Context merge into this program.\nimport type {} from '@deepseek-ai/dsh-commands'\nimport type { CommandResult } from '@deepseek-ai/dsh-commands/types'\n\n/** Cordis plugin name (the Loader entry and client bundle id). */\nexport const name = 'dsh-side-session'\n\n/** Services required before load: the command registry and the subagent runtime. */\nexport const inject = ['commands', 'subagents']\n\n/** Fixed opening prompt delivered to a freshly spawned side session. */\nconst OPENING_PROMPT = [\n  '这是一个新的旁会话。请用一两句话确认你已经就绪，并等待我输入第一个问题。',\n  'This is a new side session. Confirm in a sentence or two that you are ready, then wait for my first question.',\n].join('\\n')\n\n/** Short timestamp use